def normalize_rush_prompt(value):
    """Keep every quoted card placeholder, including adjacent alternatives."""
    if not isinstance(value, str):
        return value
    value = value.replace("？", "?").replace("（", "(").replace("）", ")").strip()
    return _QUOTED_NAME_RE.sub("{CARD}", value)

def patch_prompt(value, lang_or_pack="en"):
    """Patch one UI cell, using a prebuilt pack for efficient database builds.

    Translations derived from offline models are marked in rush_provenance.
    Card names and embedded full effect bodies are deliberately left for the
    card-text-aware caller. Runtime performs no network or model inference.
    """
    pack = build_translation_pack(lang_or_pack) if isinstance(lang_or_pack, str) else lang_or_pack
    return _patch_one_text(value, pack)

def prompt_translation_status(source, value, pack):
    """Source-aware status: Japanese text is not classified as CN by script."""
    key = normalize_rush_prompt(source)
    skipped = RUSH_PROMPT_SKIPS.get(key)
    if skipped:
        return skipped
    if not isinstance(source, str) or not source or not contains_cn_or_cn_punct(source):
        return "not_needed"
    if value == source or value == source.strip():
        return "unchanged"
    provenance = pack.get("rush_provenance", {}).get(key, "existing_patcher")
    return "draft" if provenance.startswith("offline_machine") else "translated"

